{
  "matches": [
    {
      "id": "tool:bash",
      "kind": "tool",
      "name": "bash",
      "description": "Execute a command in the shell and return combined stdout/stderr.",
      "status": "ready",
      "input_schema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string",
            "description": "Shell command to execute"
          },
          "description": {
            "type": "string",
            "description": "Optional short name for this call, in the user's language, shown in task lists."
          },
          "run_in_background": {
            "type": "boolean",
            "description": "Run detached: returns a job id immediately and keeps running across turns (no foreground timeout). Read new output with bash_output, wait with wait, stop it with kill_shell. Use for long-running commands like servers, watchers, or builds you don't need to block on."
          },
          "preserve_background_processes": {
            "type": "boolean",
            "description": "After the shell command exits normally, keep any process-group members it intentionally left behind. Use only for deliberate daemonization, browser/GUI/session launchers such as playwright-cli open, or nohup/disown/setsid; cancellation and timeouts still kill the process group."
          },
          "timeout_seconds": {
            "type": "integer",
            "description": "Deadline for this foreground call. Only tightens the host cap — a larger value is clamped to it. Output collected before the deadline is still returned, so set it low when a command's cost is unpredictable (a broad filesystem walk, a network fetch) instead of paying the full cap to find out. For work that legitimately runs long, use run_in_background.",
            "minimum": 1
          },
          "verifies": {
            "type": "string",
            "description": "Name what this call decides (e.g. \"balances.json keys are sorted\") to record it as a check. The exit status becomes the verdict, so the command must be one command or an \u0026\u0026 chain; a ';', a pipe, or '||' hands the status to something else and the call is refused."
          }
        },
        "required": [
          "command"
        ]
      }
    },
    {
      "id": "tool:complete_step",
      "kind": "tool",
      "name": "complete_step",
      "description": "Record the evidence-backed completion of ONE step of an approved plan.",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "step_id": {
            "type": "string",
            "description": "PREFERRED: the stable step_id of the task-list item this completes, e.g. \"plan_step_02\". Unlike a title or a number it survives retitles, insertions, and reordering, so cite it whenever the item has one."
          },
          "step": {
            "type": "string",
            "description": "Which plan step this completes — its title or number, matching the task list. Use only when the item has no step_id."
          },
          "step_index": {
            "type": "integer",
            "minimum": 1,
            "description": "Optional 1-based task-list item number. Use only when the item has no step_id; an index goes stale the moment a step is inserted above it."
          },
          "result": {
            "type": "string",
            "description": "What is now true or changed as a result of finishing this step."
          },
          "evidence": {
            "type": "array",
            "minItems": 1,
            "description": "Proof the step is done. At least one item is required.",
            "items": {
              "type": "object",
              "properties": {
                "criterion_id": {
                  "type": "string",
                  "description": "The acceptance criterion this proof satisfies, as the plan renders it (e.g. \"c2\" from \"accept [c2]: ...\"). Cite it whenever the step has criteria: a command succeeding is not the same as a criterion being met, and the host records the proof against the criterion you name."
                },
                "kind": {
                  "type": "string",
                  "enum": [
                    "verification",
                    "review",
                    "diff",
                    "files",
                    "manual"
                  ],
                  "description": "verification = a command/test was run (command REQUIRED); review = a built-in review run completed and, after changes, inspected the latest changed result (the verdict/findings still apply separately); diff = a concrete code change (paths REQUIRED); files = files created/edited/inspected (paths REQUIRED); manual = a manual check."
                },
                "summary": {
                  "type": "string",
                  "description": "The evidence itself: the test result, what the diff does, or what was confirmed."
                },
                "command": {
                  "type": "string",
                  "description": "REQUIRED for verification evidence: the command as it actually ran (e.g. \"go test ./...\") — it is checked against this session's real command history."
                },
                "paths": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "REQUIRED for diff/files evidence: the files this evidence refers to, as the paths were passed to the tools that touched them."
                }
              },
              "required": [
                "kind",
                "summary"
              ]
            }
          },
          "notes": {
            "type": "string",
            "description": "Optional caveats, follow-ups, or anything deferred."
          }
        },
        "required": [
          "result",
          "evidence"
        ]
      }
    },
    {
      "id": "tool:kill_shell",
      "kind": "tool",
      "name": "kill_shell",
      "description": "Terminate a running background job (bash or task) started with run_in_background.",
      "status": "ready",
      "input_schema": {
        "type": "object",
        "properties": {
          "job_id": {
            "type": "string",
            "description": "The background job id to terminate (e.g. \"bash-1\")."
          }
        },
        "required": [
          "job_id"
        ]
      }
    },
    {
      "id": "tool:task",
      "aliases": [
        "task:subagent"
      ],
      "kind": "tool",
      "name": "task",
      "description": "Spawn a sub-agent for a focused sub-task.",
      "status": "ready",
      "input_schema": {
        "type": "object",
        "properties": {
          "prompt": {
            "type": "string",
            "description": "What the sub-agent should accomplish. Be specific about the deliverable — the sub-agent does not see this conversation."
          },
          "description": {
            "type": "string",
            "description": "Short label for the sub-task (3-7 words). Surfaced in the dispatch line so the user sees what's running."
          },
          "profile": {
            "type": "string",
            "description": "Optional runAs=subagent profile name. Resolved at runtime from the Skill store; explicit names may invoke invocation=manual profiles. The profile body becomes the full system prompt."
          },
          "write_paths": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Optional workspace-relative or absolute file/directory paths this writer may modify. Prefer file paths when the targets are known: a directory overlaps every path beneath it and serializes writers. Globs and workspace escapes are rejected. Writers without write_paths claim the whole workspace (serializing against every other wr
